package com.gittexplorer.documentextractor.service.impl;
import com.gittexplorer.documentextractor.regex.RegexConfiguration;import com.gittexplorer.documentextractor.service.RegexExtractionService;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.LinkedHashSet;import java.util.List;import java.util.Map;import org.springframework.stereotype.Service;
@Service public class RegexExtractionServiceImpl implements RegexExtractionService { private final RegexConfiguration regexConfiguration; public RegexExtractionServiceImpl(RegexConfiguration regexConfiguration){this.regexConfiguration=regexConfiguration;} public Map<String,List<String>> extractIdentifiers(String text){Map<String,List<String>> results=new LinkedHashMap<>();String source=text==null?"":text;regexConfiguration.getCompiledPatterns().forEach((name,pattern)->{var matcher=pattern.matcher(source);var matches=new LinkedHashSet<String>();while(matcher.find()) matches.add(matcher.group());results.put(name,new ArrayList<>(matches));});return results;} }
